#include <stdint.h>
#include "stm32f4xx.h"
#include "stm32f411xe.h"

void init_GPIO(void);
void init_EXTI(void);

int main(void)
{
    init_GPIO();
    init_EXTI();
    /* Loop forever */
	while(1) {
        
    }
}

void init_GPIO(void) {
    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOCEN;
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;

    GPIOC->MODER &= ~(0b11 << GPIO_MODER_MODER13_Pos); //configurado como entrada

    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPDR13_Msk); //desabilita pull-up e pull-down (00)
}


void init_EXTI(void) {
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN; // Habilita o clock do SYSCFG

    SYSCFG->EXTICR[3] &= ~SYSCFG_EXTICR4_EXTI13_Msk; // Limpa a configuración de EXTI13
    SYSCFG->EXTICR[3] |= (0b0010 << SYSCFG_EXTICR4_EXTI13_Pos); //Se conecta al PIN C

    EXTI->FTSR |= EXTI_FTSR_TR13; //Activar el falling edge trigger para EXTI13
    EXTI->RTSR &= ~EXTI_RTSR_TR13; //Desactivamos el rising edge trigger para el EXTI13
    EXTI->SWIER &= ~EXTI_SWIER_SWIER13_Msk; //Desactivamos la activación por software para EXTI13
    EXTI->IMR |= EXTI_IMR_MR13;
    EXTI->PR |= EXTI_PR_PR13; //Limpiamos la bandera de interrupción para EXTI13

    
}